(()=>{
  const path=location.pathname.replace(/\/$/,'')||'/';
  const panel=typeof panels!=='undefined'&&panels.find(x=>path===`/panels/${x[0]}`);
  if(!panel)return;
  const [slug,name,,,,,,,credits]=panel;
  const annual=credits.find(x=>x[1].startsWith('12 months'));
  const creditPerUser=parseFloat(annual?.[0]||0);
  const wa=(message)=>`https://wa.me/212670779271?text=${encodeURIComponent(message)}`;
  const sports=['beIN SPORTS','Canal+ France','Sky Sports','DAZN','TNT Sports','DSTV','RMC Sport','UEFA Champions League','La Liga','Premier League','FIFA World Cup','NBA','Formula 1','UFC'];
  const vod=['Netflix','Hulu','Apple TV+','Amazon Prime Video','Disney+','HBO Max','Paramount+','Shahid VIP','OSN+'];
  const ticker=(label,items,type)=>`<section class="offer-ticker ${type}"><div class="ticker-label">${label}</div><div class="ticker-mask"><div class="ticker-track">${[...items,...items].map(item=>`<span>${item}</span>`).join('')}</div></div></section>`;
  const tier=(users,label,featured=false)=>{const total=creditPerUser*users;return `<article class="reseller-card ${featured?'featured':''}">${featured?'<span class="best-badge">MOST POPULAR</span>':''}<div class="eyebrow">${label}</div><h3>${users} users</h3><div class="credit-total">${Number.isInteger(total)?total:total.toFixed(1)} credits</div><p>${users} customer accounts × ${annual?.[0]||'annual credit'} for 12 months.</p><ul><li>✓ ${name} reseller panel</li><li>✓ 12-month account duration</li><li>✓ Credit activation support</li></ul><a class="btn ${featured?'cyan':'ghost'}" href="${wa(`Hello, I want the ${users}-user annual reseller plan for ${name} (${Number.isInteger(total)?total:total.toFixed(1)} credits).`)}" target="_blank">Request this plan</a></article>`};
  const reseller=`<section class="reseller-plans"><div class="wrap"><div class="eyebrow">Reseller annual plans</div><h2>${name} reseller plan tiers</h2><p class="sub">Annual planning based on the published 12-month credit conversion: <b>${annual?.[0]||'Confirm with sales'} per user</b>.</p><div class="reseller-grid">${tier(10,'Starter plan')}${tier(30,'Growth plan',true)}${tier(50,'Scale plan')}${tier(100,'Enterprise plan')}</div></div></section>`;
  const endUsers=`<section class="end-user-offers"><div class="wrap"><div class="eyebrow">End-user subscriptions</div><h2>${name} premium subscription plans</h2><p class="sub">Choose a long-term end-user plan. Pricing and availability are confirmed on WhatsApp before activation.</p><div class="subscription-grid"><article class="subscription-card"><div class="eyebrow">Essential plan</div><h3>12 Months</h3><p>One full year of premium access for your chosen ${name} package.</p><ul><li>✓ 4K / 60fps stream support</li><li>✓ Anti-Freeze system</li><li>✓ Sports, live TV & VOD</li><li>✓ Free M3U / Xtream test-line request</li></ul><a class="btn cyan" href="${wa(`Hello, I want the 12 Months end-user subscription for ${name}. Please send current pricing and activation details.`)}" target="_blank">Get 12-month pricing</a></article><article class="subscription-card best"><span class="best-badge">BEST VALUE</span><div class="eyebrow">Extended plan</div><h3>24 Months</h3><p>Longer coverage with discounted-duration value and priority support.</p><ul><li>✓ Everything in the 12-month plan</li><li>✓ Discounted extended duration</li><li>✓ Priority WhatsApp support</li><li>✓ Free M3U / Xtream test-line request</li></ul><a class="btn green" href="${wa(`Hello, I want the 24 Months end-user subscription for ${name}. Please send current pricing and activation details.`)}" target="_blank">Get 24-month pricing</a></article></div></div></section>`;
  const catalog=[...document.querySelectorAll('section')].find(s=>s.textContent.includes('Catalog snapshot'));
  catalog?.insertAdjacentHTML('afterend',`${ticker('LIVE CHANNELS & WORLD SPORTS',sports,'sports')}${ticker('AUTO-UPDATING VOD PLATFORMS',vod,'vod')}${reseller}${endUsers}`);
  document.head.insertAdjacentHTML('beforeend',`<style>.reseller-plans,.end-user-offers{padding:74px 0;background:linear-gradient(180deg,#0b1024,#0b1b2d)}.end-user-offers{background:#0a1020}.reseller-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin-top:28px}.reseller-card,.subscription-card{position:relative;border:1px solid #364174;border-radius:18px;padding:23px;background:linear-gradient(145deg,#121a35,#0d2233)}.reseller-card.featured,.subscription-card.best{border-color:#34d399;box-shadow:0 0 35px #34d3991f}.reseller-card h3,.subscription-card h3{font-size:27px;margin:8px 0}.credit-total{font-size:25px;font-weight:900;color:#67e8f9;margin:10px 0}.reseller-card p,.subscription-card p{color:#b7c8d6;font-size:13px}.reseller-card ul,.subscription-card ul{list-style:none;padding:0;margin:18px 0}.reseller-card li,.subscription-card li{padding:6px 0;color:#d8e9f5;border-bottom:1px solid #273657;font-size:13px}.subscription-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:30px}.best-badge{position:absolute;right:18px;top:18px;background:#34d399;color:#042f2e;font-size:10px;font-weight:900;letter-spacing:1px;padding:7px 9px;border-radius:7px}.offer-ticker{padding:16px 0;border-top:1px solid #293452;border-bottom:1px solid #293452;background:#0a0e20;overflow:hidden}.offer-ticker.vod{background:#101526}.ticker-label{max-width:1180px;margin:0 auto 10px;padding:0 24px;color:#67e8f9;font:700 11px 'DM Mono',monospace;letter-spacing:1.3px}.ticker-mask{overflow:hidden}.ticker-track{display:flex;width:max-content;gap:12px;animation:offerMarquee 34s linear infinite}.vod .ticker-track{animation-duration:27s;animation-direction:reverse}.ticker-track span{display:inline-flex;align-items:center;justify-content:center;min-width:155px;padding:10px 14px;border:1px solid #33426a;border-radius:999px;background:#151b32;color:#e6f6ff;font-size:13px;font-weight:800}.sports .ticker-track span:nth-child(3n){color:#67e8f9}.vod .ticker-track span:nth-child(3n){color:#a78bfa}@keyframes offerMarquee{to{transform:translateX(-50%)}}.ticker-mask:hover .ticker-track{animation-play-state:paused}@media(max-width:900px){.reseller-grid{grid-template-columns:1fr 1fr}}@media(max-width:700px){.reseller-plans,.end-user-offers{padding:52px 0}.reseller-grid,.subscription-grid{grid-template-columns:1fr}.reseller-card,.subscription-card{padding:22px}.ticker-label{padding:0 18px}.ticker-track span{min-width:138px;font-size:12px}}</style>`);
})();
